<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/private/auth.php';
if(!installed()){header('Location: install.php');exit;}
header('Cache-Control: no-store');
session_start_safe();
$db=pdo();auth_migrate($db);
$error='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST' && isset($_POST['login'])) {
    try {
        verify_csrf();
        $email=(string)($_POST['email']??'');
        $password=(string)($_POST['password']??'');
        if (!auth_login($email,$password)) throw new RuntimeException('Incorrect credentials or temporarily locked account. Please try again later.');
        header('Location: index.php',true,303);exit;
    }catch(Throwable $e) {
        // Never expose whether an email address exists.
        $error=$e instanceof PDOException ? 'Sign-in is temporarily unavailable.' : $e->getMessage();
    }
}
$me=auth_current_user();
function esc(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if(!$me): ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · Guia Lanka Photo Manager</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-bg"><main class="auth-card"><div class="brand-badge">GL</div><div class="eyebrow">PRIVATE PHOTO LIBRARY</div><h1>Welcome back</h1><p>Sign in to organize your Sri Lankan travel photographs.</p><?php if($error):?><p role="alert" class="alert"><?=esc($error)?></p><?php endif;?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=esc(csrf_token())?>"><label>Email address<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button type="submit" name="login" value="1" class="button primary">Sign in</button></form><p class="fine">Access is by invitation only. If you forgot your password, contact your administrator for a one-time reset link.</p><?php if(isset($_GET['password_set'])):?><p role="status" class="notice">Password saved. You can now sign in.</p><?php endif;?></main></body></html>
<?php exit;endif; ?>
